        "desc": "堺市制100周年を機に開いた築山林泉回遊式の庭で、2.6haの敷地に滝や流れ、池がしつらえられ、和室で抹茶と生菓子をいただける。すぐ隣にある古墳の張りつめた静けさとは対照的に、ここは人の手で整えられた緑のやわらかさがある——森を「仰ぐ」場所から、緑の「中を歩く」場所へと気分が切り替わる。月曜などの休園日があり、入園は有料。茶席の提供時間や料金は変わるので、訪問前に公式サイトで確かめておきたい。",
