    "subtitle": "大阪・住吉 ｜ SUMIYOSHI WALK",
    "lede": "阪堺電車のチンチンという鐘が遠ざかると、急に音が引いた。紀州街道を一本またいだだけなのに、車の地鳴りが松の梢の高さで濾されて、足元に届くのは砂利を踏む自分の靴音ばかりになる。朱の大鳥居をくぐると、目の前に弓なりの橋が立ち上がっていた。空へ向かってそり返るその朱色を、住吉の人は「太鼓橋」と呼んでならい育つのだという。海に近い土地の光はどこか白っぽく、橋の朱を一段とあざやかに見せる。きょうはこの橋を渡って、潮の名を残す参道の奥まで、ゆっくり歩いてみる。",
    "date": "2026-06-14",
