        "desc": "鳥居を出て紀州街道を西へまたぐと、松並木の続く広い道に出る。これが汐掛道、潮を掻きながら浜へ向かった頃の名を残す住吉大社の表参道で、いまは住吉公園を東西に貫いている。住吉公園は明治六年に開かれた大阪府営第一号の公園で、もとは住吉大社の社域だった一帯が公園として開放された。松の下を西の端まで抜け、国道二十六号をはさんだ浜口西のたもとまで来ると、高さ十六メートルほどの住吉高燈籠が立っている。鎌倉期に灯がともされたと伝わり、日本最古の灯台ともいわれる常夜灯で、いまの塔は昭和に元の場所から東へ移して鉄筋で建て直されたもの。かつてはここから海が見え、沖の船がこの灯りを目印にしたという。内部は史料館として公開されているが日が限られるため、立ち寄るなら公開日と時間を住吉名勝保存会の案内で先に確かめておきたい。",
