    "quote": "渡りきって振り返ると、橋はもう自分の背中側にある。住吉を歩くとは、たぶんそういう順番でしか味わえない。",
    "quoteCite": "マチノワ編集部",
    "closing": "汐掛道を西へ抜けて高燈籠の足元まで来ると、参道のにぎわいはすっかり背中に遠い。かつてここから海が見えたのだと聞いても、いまは国道の向こうにビルが並ぶばかりで、潮の気配は松籟のなかにしか残っていない。それでも、橋を渡り、本宮に手を合わせ、五所御前で小石をひろうという順に体を運んでみると、住吉という土地が長いあいだ「海へ向かって祈ってきた場所」だったことが、足の裏のほうから腑に落ちてくる。来た道を戻れば、また反橋の朱が松の間からのぞく。さんぽの締めくくりは、行きとは逆向きに橋を見上げることにした。なお参拝時間や授与所の受付、各施設の公開日は折々で変わるので、出かける前に住吉大社や各館の公式の知らせに目を通しておくと安心だ。"
