    "articleType": "guide",
    "kicker": "OTSU BIWAKO",
    "title": "大津、琵琶湖の水辺をたどる。湖港と古社を歩く一日",
    "titleHTML": "大津、琵琶湖の水辺をたどる。<br>湖港と古社を歩く一日",
    "subtitle": "さんぽ / OTSU BIWAKO",
    "lede": "大津のまちは、背中に比叡や長等の山を負い、顔を琵琶湖へ向けて細長く伸びている。だから水辺を軸に歩くと、この街の輪郭がすっと掴める。湖そのものを船で渡り、湖へ注ぐ瀬田川のほとりに建つ古刹で石を仰ぎ、山裾の泉を抱えた寺で湧き水の音を聞き、御所跡の杜で時を計った人を思い、最後は湖畔の庭で花越しに対岸を眺める。一日を通して耳に残るのは、岸を打つ波と、注ぎ込む川の流れと、境内を巡る水の音だ。湖に近づいたり離れたりを繰り返しながら、水のかたちが場所ごとにこれほど違うのかと気づく――それがこの水辺さんぽのいちばんの面白さだと思う。",
