        "desc": "外輪を両舷に備えた大型船ミシガンが発着する、大津の玄関口。陸からいくら湖を眺めても、自分が湖に「囲まれている」感覚は得られないが、岸を離れて数分も進むと、比叡から長等へと連なる山並みが湖面の向こうに横一列に並び、大津のまちが山と水の間の細い帯であることが一目で分かる。デッキに出れば近江大橋や対岸の集落が水平に流れていき、この街がなぜ港から発展したのかが体感として腑に落ちる。運航するコースや時間帯は時期で変わるので、乗る便は運航会社の公式案内で確かめてから港へ向かいたい。",
