        "desc": "天智・天武・持統の三天皇の産湯に用いたと伝わる霊泉が湧くことから「御井（みい）の寺」と呼ばれ、それが三井寺の名の由来になった。今もその井戸からは水が湧き続け、覆い屋の中で水音が静かに反響している。広い境内は長等山の斜面に沿って広がり、観音堂のあたりまで登ると、堂の屋根越しに琵琶湖と大津の市街が一望できる。湖を「見上げる」石山寺に対し、こちらは湖を「見下ろす」位置にある寺で、同じ水辺でも視点がまるで違う。拝観の受付時間や料金は変動するので、最新は寺の公式情報で確かめてほしい。",
