        "desc": "飛鳥から都を移し、この湖畔に近江大津宮を置いた天智天皇を祀る社。境内には、天皇が日本で初めて時を知らせたという漏刻（水時計）を復元した装置が据えられ、滴る水で時を計った時代が偲べる。日本の時刻制度発祥の地として時計に縁が深く、参道の朱塗りの楼門は山の緑に映えて端正だ。百人一首の巻頭歌を詠んだ天智天皇にちなみ、かるたの聖地としても親しまれている。湖そのものは見えないが、なぜここに都が築かれたかを思えば、水辺さんぽの輪の中にしっかり収まる一社である。",
