        "desc": "昭和9年に国際観光ホテル「琵琶湖ホテル」として建てられた建物を保存改修した施設で、城郭を思わせる瓦屋根の本館がそのまま残る。建物に隣り合う柳が崎湖畔公園には西洋式の回遊庭園が広がり、季節ごとの花を縫って歩くと、生け垣の切れ目から琵琶湖がふいに開ける。船で離れた湖面に、一日の終わりにこうして再び並ぶと、巡ってきた港や寺の位置が湖を挟んで思い出せる。庭園の入園料や開園期間は時期で変わるため、訪問前に施設の公式ページで確かめておきたい。本館の見学そのものは気軽に立ち寄れる。",
