    "kicker": "OMIHACHIMAN",
    "title": "近江八幡・八幡堀を歩く。白壁と水路の近江商人の町",
    "titleHTML": "近江八幡・八幡堀を歩く。<br>白壁と水路の近江商人の町",
    "subtitle": "石垣に水がひたひたと寄せる、商人の町の半日",
    "lede": "近江八幡駅の北口を出て、バスに七分ほど揺られると、車窓の景色が瓦屋根と白壁に変わってくる。八幡堀（大杉町）八幡山ロープウェー口で降りると、まず耳が気づく。車の音が遠のいて、かわりに水が石垣にひたひたと触れる、低くやわらかい音がする。八幡堀だ。柳が水面に枝を垂らし、岸の蔵が水鏡に逆さまの姿を落としている。観光地というより、いまも町の呼吸がそのまま残っている場所、という手ざわりがある。日傘を差した人がゆっくり橋を渡っていく。その後ろを、わたしも歩きはじめる。",
    "date": "2026-06-14",
    "reading": "約4分",
    "author": "マチノワ編集部",
