    "quote": "水のおもてに、白壁の蔵がもう一度立っている",
    "quoteCite": "マチノワ編集部",
    "closing": "気づけば日が傾いて、堀の水が金色を帯びてきた。蔵の白壁が夕日を吸って、朝とは別の表情に変わっている。この町は、近江商人が物資を運んだ水路と、彼らが財を投じて遺した屋敷、そしてアメリカから渡ってこの地に根を下ろした建築家ヴォーリズ（ウィリアム・メレル・ヴォーリズ）が遺した西洋建築とが、一つの川岸に折り重なっている。今日歩いた草屋根のラ コリーナは藤森照信による現代の設計で、ヴォーリズ建築とはまた別の系譜だが、どちらもこの町の懐の深さを物語っている。早足で回れば二時間ほどだが、橋のたもとで水音を聞いたり、堀端のベンチでひと休みしたりしているうちに、半日があっという間に過ぎた。和船や各施設の運航・開館の時間は季節で動くので、出かける前に公式サイトをのぞいておくと安心だ。柳の影が長く伸びる頃、もう一度堀沿いを駅へ向かって歩く。来たときと同じ水音が、帰りはなぜか名残惜しく聞こえた。"
