        "desc": "1933年竣工の市庁舎で、県庁とともに国の重要文化財に指定されている。屋根に和風の意匠を載せた点は隣の県庁と通じるが、こちらは中央の時計塔が特徴で、その頂には東西南北をにらむ四方睨みの鯱が据えられている――城の金鯱を一日の終わりにもう一度、形を変えて見ることになる。県庁とは目と鼻の先なので、二棟を並べて昭和初期の名古屋が選んだ「城に倣う」流儀を比べてから駅へ抜けると、コースがきれいに閉じる。",
