    "closing": "日本平の回廊をぐるりと一周すると、午前に歩いた松原も、船で渡った港も、ぜんぶ足下の景色のなかに小さく収まっていた。半日かけて地面を這うように見てきたものが、ここでは手のひらにのる。富士は雲に隠れたり出たりを繰り返していて、結局この日いちばん長く眺めたのは、富士そのものより、富士を待つ自分の時間だったかもしれない。海風で乾いた頬のまま、来た道を目で辿る。歩いて、乗って、また見上げて——清水という街は、視点を変えるたびに表情を変える街だった。なお各施設の時間や料金は折にふれ見直されるので、出かける前にそれぞれの公式ページをのぞいておくと安心だ。"
