        "desc": "夫婦岩を見たあと、その同じ二見ヶ浦の浜辺に面して建つのがこのリゾートモール。カフェや和食店、ジェラート店などが集まり、なかでもSURF SIDE CAFEは海岸線を見渡す大きなガラス窓が席のすぐ前にあり、波の高さや日差しの角度が刻々と変わるのを眺めながら自家製パスタやピッツァを味わえる。海を「見にいく」のではなく「窓の向こうにずっと置いたまま」過ごせるのが、わざわざここで足を止める理由だ。浜は糸島市と福岡市西区にまたがるが、この複合施設の住所は福岡市西区西浦にあたる。昼はリゾート気分、夕方は同じ窓がそのままサンセットの額縁に変わる。メニューや各店の営業日・営業時間は店ごとに違うため、訪問前に施設の公式案内で確かめておくとよい。",
