    "subtitle": "舟がくぐる橋の下、櫂の雫が落ちる音。水とともに暮らしてきた城下町を、流れに沿ってたどる",
    "lede": "柳川では、まず水の匂いに気づく。駅を出て少し歩くと、家々のあいだを縫って細い水路が現れ、そこに棹を握った船頭の声がのんびり響いている。掘割と呼ばれるこの水の道は、かつて城を守り、田を潤し、暮らしの水を運んだもの。観光のために掘られたわけではなく、町のほうがこの水に合わせて形づくられてきた。だから柳川を歩くというのは、水のかたちを目でなぞることでもある。空が広く、柳がときどき風で揺れる。さあ、低い橋をいくつもくぐりながら、流れの下流へ向かって町を抜けていこう。",
