        "desc": "棹を握った船頭が町の昔話や舟唄を挟みながら、頭がつかえそうなほど低い石橋を一つずつくぐっていく。城堀の水門から内堀へ入って沖端あたりまで、約3キロを一時間ほどかけて折れ曲がりながら下るのが定番の流れだ。水面すれすれを進むので、柳の枝が頬をかすめ、岸の蔵や生け垣を見上げる格好になる。冬場はこたつを据えた舟になり、毛布にくるまって白い息を吐きながら下れるのが柳川ならでは。運航は天候で変わるので、出発前に乗船場の最新案内を確かめておきたい。",
