        "desc": "門をくぐると、明治期に建てられた西洋館と、池を中心に据えた松濤園が現れる。この松濤園は仙台の松島を写したと伝わる池泉庭園で、岸辺に植えられた松と水面の取り合わせが、ここが大名の住まいだった時代をそのまま今に運んでくる。大広間からは庭が一枚の絵のように開け、立花家史料館では甲冑や調度が当主の暮らしを物語る。掘割の水とつながる立地そのものが、柳川における立花家と水の縁を物語っている。開館の時間帯は季節で前後するため、訪ねる前に公式の案内を一読しておくとよい。",
