        "desc": "白い漆喰のなまこ壁が水路際に続く一画に、詩人・北原白秋の生家がそのまま残る。実家は造り酒屋だったといい、太い梁の通る土間や帳場に、明治の柳川の暮らしの匂いがこもっている。白秋は故郷の水郷を「わが生ひ立ち」などに繰り返し描いた人で、ここを訪ねてから掘割を見ると、舟も柳も橋もどこか詩の一節のように見えてくるから不思議だ。隣接する記念館には自筆原稿や愛用の品が並び、言葉が生まれた土地と作品が地続きであることを実感させる。開館は午後の早い時間で閉まるので、巡る順番を考えておきたい。",
