        "desc": "掘割が下流で広がるあたり、水際にぽつりと小さな社が立つ。明治のはじめに久留米水天宮の分霊を勧請し、地元の稲荷神社などを合祀して創られた、水の安全を司る神社だ。圧巻は春の祭礼で、社の横の掘割に六隻の川舟をつないで組み上げた「三神丸」という舟の舞台が浮かび、その上で三日三晩、踊りや芝居が奉納される。流れる調子に異国めいた響きが混じることから「オランダ囃子」とも呼ばれるその囃子は、水の上で聞くからこそ独特の余韻を残す。祭礼の日程は毎年告知されるので、合わせて訪ねるなら最新の案内を確かめて。",
