    "lede": "伊香保の街は、平らな場所がほとんどない。榛名山の東斜面にしがみつくように宿が積み重なり、その背骨を貫いているのが365段の石段だ。面白いのは、坂をのぼっているあいだ、ずっと足元に温泉が流れているということ。石段の下には茶褐色の「黄金の湯」の源泉が走り、16か所の小間口（こまぐち）と呼ばれる分湯口から、両脇の宿へ湯が引かれていく。つまりこの坂さんぽは、湯が山から降りてくる道を、人間が逆にさかのぼっていく行為でもある。息を切らして一段ずつのぼり、てっぺんの神社で源泉の気配に触れ、さらにロープウェイで一気に頂へ抜ける――そこから足を延ばせば、山あいの古刹・水澤観音が待っている。この記事は、そういう「縦に長い湯の街」を、坂の高低差そのものを楽しむ目線でたどっていく。",
