    "lede": "秩父を歩くと、地形そのものが見どころなのだと気づく。盆地を囲む山が荒川を細くしぼり、その水が長い時間をかけて岩を削り、渓谷をつくった。芝桜が色を敷きつめる丘も、岩がむき出しになった川床も、磨崖仏が刻まれた砂岩の壁も、もとをたどればこの土地の成り立ちにつながっている。だからこの特集は、花や社を点で訪ねるというより、「水と岩がつくった風景」を一本の線で読むつもりで組んだ。芝桜の丘で盆地を見渡し、川へ下りて岩畳に立ち、山上の社で霧に包まれる——標高差をそのまま味わう道のりにした。",
