        "desc": "秩父札所三十四所のひとつで、深い谷の奥、岩壁を背にして本堂が建つ。観音院が忘れがたいのは、本堂脇にかかる高さ約30メートルの聖浄の滝と、その左手の岩壁に小さな磨崖仏がびっしりと刻まれた「鷲窟磨崖仏」が間近に迫ること。岩肌は約1,700万年前の海底でできた砂岩で、よく見ると堆積した当時の水流の跡まで残っている。この谷では、地質の時間と人の祈りが文字どおり同じ岩の上に重なっている。山門までの徒歩と296段の石段で札所のなかでも歩きごたえがあり、谷を上り下りしてようやくたどり着く感覚そのものが、この札所の体験の核になっている。足回りは歩きやすい靴を選びたい。",
