    "quote": "水が削り、岩が残り、人が祈った。秩父の谷は、その三つの層が重なって今の景色になっている。",
    "quoteCite": "マチノワ編集部",
    "closing": "花の丘から渓谷、そして雲の上の社まで、ひとつの川がつないでいる土地だった。季節で表情がまるごと変わるのも秩父の面白さなので、芝桜・蝋梅・紅葉と、狙う時期を決めてから出かけると満足度が高い。なお拝観時間や乗船料、ロープウェイ運賃、バスの運賃・ダイヤは季節や改定で動くことがある。荒川ライン下りや宝登山ロープウェイ、西武観光バス、各社寺の公式発信に出発前に一度目を通しておくと、当日あわてずに済む。"
