        "desc": "まず足を向けたのは根津神社だった。表参道の楼門をくぐると、朱と黒に総漆塗りされた権現造の社殿が現れる。本殿・幣殿・拝殿をひと棟につなぐこの様式は、五代将軍綱吉の時代に整えられたもので、社殿をふくむ七棟が国の重要文化財に指定されている。江戸の大火や戦災をくぐり抜けて当時のまま残る社殿は、東京の市街地では数えるほどしかない。境内の池のほとりには乙女稲荷があり、傾斜地に沿って朱の鳥居が幾重にも連なっている。鳥居のトンネルを抜けると視界が開け、つつじの植え込みが斜面いっぱいに広がる。例年春に開かれるつつじまつりの頃には約百種が一斉に色づくが、花の盛りや入苑の案内は時期で変わるため、訪ねる前に神社の公式サイトを覗いておきたい。",
