        "desc": "ギャラリーを出て寺町の小道に折れると、片側の景色が一変する。観音寺の境内南面に沿って、瓦と粘土を交互に積み上げた練り塀が四十メートル近く続いているのだ。土と瓦を層にして固め、上から屋根瓦をふいたこの築地塀は、江戸期の土塀がそのまま残る数少ない例で、国の登録有形文化財になっている。塀に手をあてると瓦の縞が指に触れ、長い年月のあいだ風雨に削られてきた表面のざらつきが伝わってくる。観音寺は赤穂義士ゆかりの寺としても知られるが、この道の魅力はむしろ静けさにある。日暮里駅から数分の距離とは思えないほど物音が少なく、塀ぞいの一本道だけが切り取られたように江戸の寺町の気配をとどめている。",
